def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    after_D_C = 0
    after_D_D = 0

    for i in range(n):
        my_a, opp_b = history[i]
        if opp_b == 'C':
            opp_c += 1
        if i > 0 and history[i-1][0] == 'D':
            if opp_b == 'C':
                after_D_C += 1
            else:
                after_D_D += 1

    my_last, opp_last = history[-1]
    opp_d = n - opp_c

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_streak += 1
        else:
            break

    start5 = n - 5
    if start5 < 0:
        start5 = 0
    recent5_c = 0
    for i in range(start5, n):
        if history[i][1] == 'C':
            recent5_c += 1

    start10 = n - 10
    if start10 < 0:
        start10 = 0
    recent10_c = 0
    for i in range(start10, n):
        if history[i][1] == 'C':
            recent10_c += 1
    recent10_len = n - start10
    recent10_d = recent10_len - recent10_c

    if (
        n >= 88
        and after_D_C >= 2
        and after_D_C > after_D_D
        and opp_c * 10 >= n * 8
        and recent10_c >= 8
    ):
        if opp_last == 'C' or recent5_c >= 4:
            return 'D'

    if my_last == 'D' and opp_last == 'D':
        if dd_streak >= 3 and opp_c * 10 >= n * 7:
            return 'C'
        if opp_d_streak <= 5 and opp_c * 10 >= n * 5 and recent10_c >= 2:
            return 'C'

    if opp_c == 0:
        return 'D'
    if opp_d_streak >= 8 or recent10_d >= 7:
        return 'D'
    if opp_d * 10 >= n * 7:
        return 'D'

    if recent10_c >= 9 or recent5_c >= 5:
        return 'C'
    if opp_c * 10 >= n * 8:
        return 'C'

    if opp_last == 'D':
        if my_last == 'C':
            if opp_d_streak <= 4 and opp_c * 10 >= n * 5 and recent10_c >= 3:
                return 'C'
            return 'D'
        else:
            if opp_d_streak <= 5 and opp_c * 10 >= n * 5 and recent10_c >= 2:
                return 'C'
            if dd_streak >= 3 and opp_c * 10 >= n * 7:
                return 'C'
            return 'D'

    if my_last == 'D':
        if (
            n >= 80
            and after_D_C >= 1
            and after_D_C > after_D_D
            and opp_c * 10 >= n * 8
            and recent5_c >= 4
        ):
            return 'D'
        return 'C'

    return 'C'
